const circularShift = (x, shift) => {
  const s = String(x);
  const n = s.length;
  if (shift > n) {
    return s.split('').reverse().join('');
  }
  if (shift === 0) {
    return s;
  }
  const shifted = s.slice(n - shift) + s.slice(0, n - shift);
  return shifted;
};
