const strangeSortList = (lst) => {
  if (lst.length === 0) return [];

  const arr = [...lst];
  const result = [];

  while (arr.length > 0) {
    // Find minimum
    let minIdx = 0;
    for (let i = 1; i < arr.length; i++) {
      if (arr[i] < arr[minIdx]) minIdx = i;
    }
    result.push(arr[minIdx]);
    arr.splice(minIdx, 1);

    if (arr.length === 0) break;

    // Find maximum
    let maxIdx = 0;
    for (let i = 1; i < arr.length; i++) {
      if (arr[i] > arr[maxIdx]) maxIdx = i;
    }
    result.push(arr[maxIdx]);
    arr.splice(maxIdx, 1);
  }

  return result;
};
