const isMultiplyPrime = (a) => {
  const isPrime = (n) => {
    if (n < 2) return false;
    for (let i = 2; i * i <= n; i++) {
      if (n % i === 0) return false;
    }
    return true;
  };

  const count = (n) => {
    let count = 0;
    for (let i = 2; i * i <= n; i++) {
      while (n % i === 0) {
        count++;
        n /= i;
      }
    }
    if (n > 1) count++;
    return count;
  };

  return count(a) === 3 && isPrime(a);
};
